import{_ as t,b as l,c as o,g as e}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"美国纽约摄影学院摄影教材","description":"","frontmatter":{"title":"美国纽约摄影学院摄影教材","subTitle":"光线","author":"oasis","date":"2026-09-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/nyip-course/3.md","filePath":"articles/books/nyip-course/3.md"}'),s={name:"articles/books/nyip-course/3.md"};function r(a,i,n,p,d,_){return l(),o("div",null,[...i[0]||(i[0]=[e('<h2 id="光线分类" tabindex="-1">光线分类</h2><ol><li>自然光</li><li>现场光</li><li>人造光</li></ol><h2 id="光线特征" tabindex="-1">光线特征</h2><ol><li>明暗度</li><li>方向</li><li>色彩</li></ol><h2 id="光的四个基本方向" tabindex="-1">光的四个基本方向</h2><p>这里的角度是主体和光源的角度。</p><ol><li><strong>正面光</strong></li><li><strong>45 度光</strong>：可以产生很好的光和影的相互作用，影调体现一种立体感，被称为「自然光」。</li><li><strong>90 度光</strong>：称为「结构光」，阴影和高光的对比强烈。</li><li><strong>逆光</strong>：适合创造简洁又具表现力的高反差影像。</li></ol><h2 id="现场光" tabindex="-1">现场光</h2><p>现场光包含室内光源、从窗户进来的太阳光，不含溢光灯、闪光灯。</p><p>现场光的特点：</p><ul><li>真实和情调</li><li>使用方便</li><li>摄影对象容易放松</li></ul><h2 id="人造光" tabindex="-1">人造光</h2><p>频闪灯不是一种特殊的「光」，而是一种能在极短时间内释放大量光能的光源。</p><p>真正冻结运动的，不一定是相机快门，而可能是闪光本身的持续时间。这是非常重要的摄影概念。</p>',14)])])}const u=t(s,[["render",r]]);export{h as __pageData,u as default};
